#include "SiteRetirementRuntime.hpp"
namespace elysium::fortress {bool SiteRetirementRuntime::add(SiteRepresentation s,std::string&w){if(!s.site||!s.generatorFingerprint){w="invalid site representation";return false;}return rows_.emplace(s.site,std::move(s)).second;}bool SiteRetirementRuntime::retire(StableId id,bool frozen,std::string&w){auto i=rows_.find(id);if(i==rows_.end()||i->second.state!=RepresentationState::Detailed){w="site not detailed";return false;}if(!frozen){w="local commits not frozen";return false;}i->second.state=RepresentationState::Strategic;++i->second.historyRevision;return true;}bool SiteRetirementRuntime::strategicAdvance(StableId id,std::uint64_t d,std::string&w){auto i=rows_.find(id);if(i==rows_.end()||i->second.state!=RepresentationState::Strategic){w="site not strategic";return false;}i->second.aggregatePopulation+=d;++i->second.historyRevision;return true;}bool SiteRetirementRuntime::reclaim(StableId id,ContentId fp,bool mig,std::string&w){auto i=rows_.find(id);if(i==rows_.end()||i->second.state!=RepresentationState::Strategic){w="site not reclaimable";return false;}if(i->second.generatorFingerprint!=fp&&!mig){w="generator fingerprint mismatch";return false;}i->second.state=RepresentationState::Detailed;++i->second.entityRevision;return true;}std::optional<SiteRepresentation>SiteRetirementRuntime::get(StableId id)const{auto i=rows_.find(id);if(i==rows_.end())return std::nullopt;return i->second;}}
